/** Generated from the overhaul textbook. Re-run tools/import-overhaul-courses.mjs. Do not edit by hand. */
export default {"id":"launchkey-level-14","number":14,"title":"Live Pad Subsystems Clip Launch, Step Sequencer & Drums","skillBand":"Textbook","duration":"From the course textbook","summary":"When connected to Ableton Live 12, the 16 RGB pads on the Launchkey MK4 61 function as a tactile Session View interface in Clip Mode. This module covers mode selection, RGB optical telemetry (clip presence, cued states, playback pulses, rec","modules":[{"id":"launchkey-m-14-1-1","code":"14.1","title":"Live Pad Subsystems: Clip Launch, Step Sequencer & Drums","blurb":"When connected to Ableton Live 12, the 16 RGB pads on the Launchkey MK4 61 function as a tactile Session View interface in Clip Mode. This module covers mode selection, RGB optical telemetry (clip presence, cued states, playback pulses, rec","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"launchkey-l-o-42","title":"Section overview","blocks":[{"type":"step","title":"Section 14.1 — Live Clip Launching Pad Engine","blocks":[{"type":"heading","text":"Module Overview","level":3},{"type":"prose","html":"When connected to Ableton Live 12, the 16 RGB pads on the Launchkey MK4 61 function as a tactile Session View interface in <strong>Clip Mode</strong>. This module covers mode selection, RGB optical telemetry (clip presence, cued states, playback pulses, recording states), scene launching, and the 4-tier <code>Function</code> button track management cycle (Stop, Mute, Solo)."},{"type":"heading","text":"Learning Objectives","level":3},{"type":"list","items":["Engage Session Clip Mode via the <code>Shift + Pad 9</code> command.","Formulate the comprehensive 6-state optical color and animation matrix for Session clips.","Execute horizontal scene triggering via the <code>Scene Launch &gt;</code> button.","Cycle the bottom pad row across <strong>Clip Launch</strong>, <strong>Track Stop</strong>, <strong>Track Mute</strong>, and <strong>Track Solo</strong> using the <code>Function</code> button."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-14-1-1","title":"14.1.1: Clip Mode Initialization & Overview","blocks":[{"type":"step","title":"14.1.1: Clip Mode Initialization & Overview","blocks":[{"type":"list","items":["<strong>Activation</strong>: Hold <code>Shift</code> and press <strong>Pad 9</strong> once (silkscreened <code>DAW</code>).","<strong>OLED Feedback</strong>: Displays <code>Pad Mode: Clip (1/2)</code>.","<strong>Session Focus</strong>: The 16 pads map directly to the 2×8 rectangular highlight box visible in Ableton Live’s Session View (Top Row = Scene Row 1, Bottom Row = Scene Row 2)."],"ordered":false}]}],"minutes":8},{"id":"launchkey-l-14-1-2","title":"14.1.2: Authoritative RGB Optical Telemetry Matrix","blocks":[{"type":"step","title":"14.1.2: Authoritative RGB Optical Telemetry Matrix","blocks":[{"type":"prose","html":"The pads provide real-time status feedback for all 16 mapped clip slots:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------------+\n|                    LIVE SESSION CLIP OPTICAL TELEMETRY MATRIX                 |\n+-----------------------+-----------------------+-------------------------------+\n| Clip Status in Live   | Pad Optical State     | Animation Behavior            |\n+-----------------------+-----------------------+-------------------------------+\n| **Empty Slot**        | **Unlit / Extinguished| Zero light emission           |\n| **Stopped Clip**      | **Solid Track Color** | Constant steady illumination  |\n| **Cued to Launch**    | **Flashing Green**    | Rapid periodic blink (waiting)|\n| **Actively Playing**  | **Pulsing Green**     | Smooth rhythmic pulse (tempo) |\n| **Cued to Record**    | **Flashing Red**      | Rapid periodic red blink      |\n| **Actively Recording**| **Pulsing Red**       | Smooth rhythmic red pulse     |\n+-----------------------+-----------------------+-------------------------------+</pre>"}]}],"minutes":8},{"id":"launchkey-l-14-1-3","title":"14.1.3: Scene Launching","blocks":[{"type":"step","title":"14.1.3: Scene Launching","blocks":[{"type":"list","items":["Positioned to the right of Pad 8 is the <code>Scene Launch &gt;</code> button.","<strong>Operation</strong>: Pressing <code>Scene Launch &gt;</code> triggers all clips residing within the top row scene of the current 2×8 focus ring simultaneously.","<strong>Color Mirroring</strong>: The button illuminates in the exact color assigned to that scene in Ableton Live."],"ordered":false}]}],"minutes":8},{"id":"launchkey-l-14-1-4","title":"14.1.4: The 4-Tier Function Track Management Cycle","blocks":[{"type":"step","title":"14.1.4: The 4-Tier Function Track Management Cycle","blocks":[{"type":"prose","html":"Pressing the physical <code>Function</code> button dynamically transforms the <strong>bottom row of pads (Pads 9–16)</strong> into dedicated track mixer controllers:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------------+\n|                    FUNCTION BUTTON ROW MANAGEMENT CYCLE                       |\n+----+------------------+-----------------------+-------------------------------+\n| Step| Mode Name       | Function Button Color | Bottom Row (Pads 9–16) Action |\n+----+------------------+-----------------------+-------------------------------+\n| 1  | **Clip Launcher**| Baseline / Unlit      | Normal 2nd Scene Clip Launch  |\n+----+------------------+-----------------------+-------------------------------+\n| 2  | **Track Stop**   | **Solid RED**         | Pads illuminate **Red**:      |\n|    |                  |                       | Bright Red = Clip playing     |\n|    |                  |                       | Press pad to STOP track clip  |\n+----+------------------+-----------------------+-------------------------------+\n| 3  | **Track Mute**   | **Solid ORANGE**      | Pads illuminate **Orange**:   |\n|    |                  |                       | Dim = Track Active            |\n|    |                  |                       | Bright = Track Muted          |\n+----+------------------+-----------------------+-------------------------------+\n| 4  | **Track Solo**   | **Solid BLUE**        | Pads illuminate **Blue**:     |\n|    |                  |                       | Bright Blue = Track Soloed    |\n+----+------------------+-----------------------+-------------------------------+</pre>"},{"type":"prose","html":"<em>Continuous Cycle</em>: Pressing <code>Function</code> while in Solo mode cycles back to Step 1 (standard Clip Launcher)."}]},{"type":"step","title":"Operational Rules Summary","blocks":[{"type":"list","items":["<strong>mustCover</strong>: Mode selection (<code>Shift + Pad 9</code> once); all 6 clip optical states (empty, color, flash green, pulse green, flash red, pulse red); Scene Launch color mirroring; 4-tier Function cycle (Clips -&gt; Stop -&gt; Mute -&gt; Solo).","<strong>mustNotCover</strong>: Invention of 8×8 Launchpad clip grids."],"ordered":false}]},{"type":"step","title":"Practical Guided Task & Assessment Checkpoint","blocks":[{"type":"prose","html":"<strong>Task</strong>: In Ableton Live, create a session with 4 active clips. Launch two clips from the Launchkey pads, observe pulsing green playback, press <code>Function</code> to enter Stop Mode (Red), stop Track 1, press <code>Function</code> to enter Mute Mode (Orange), mute Track 2, and press <code>Function</code> to cycle back to standard Clip mode."},{"type":"prose","html":"<strong>Checkpoint Validation</strong>:"},{"type":"list","items":["Pad optical states accurately reflect empty, stopped, playing, and recording states.","Function button cycles cleanly through Stop, Mute, Solo, and Clip launcher modes."],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"launchkey-m-14-2-2","code":"14.2","title":"Live Pad Subsystems: Clip Launch, Step Sequencer & Drums","blurb":"The native Ableton Live Step Sequencer embedded in the Launchkey MK4 61 transforms the 16 RGB pads into a hardware step sequencer that reads, edits, and creates MIDI clips directly inside Ableton Live 12. This module covers sequencer initia","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"launchkey-l-o-43","title":"Section overview","blocks":[{"type":"step","title":"Section 14.2 — 16-Step Clip Step Sequencer","blocks":[{"type":"heading","text":"Module Overview","level":3},{"type":"prose","html":"The native Ableton Live Step Sequencer embedded in the Launchkey MK4 61 transforms the 16 RGB pads into a hardware step sequencer that reads, edits, and creates MIDI clips directly inside Ableton Live 12. This module covers sequencer initialization, automatic clip instantiation, 16-step grid layout, multi-bar sequence paging, and hardware clip length doubling."},{"type":"heading","text":"Learning Objectives","level":3},{"type":"list","items":["Initialize the Live Step Sequencer via the secondary DAW pad command (<code>Shift + Pad 9</code> pressed twice).","Formulate the contextual behavior of the sequencer across empty MIDI tracks, populated MIDI clips, and audio tracks.","Detail the 16-step bar architecture and white playhead synchronization.","Navigate multi-bar sequences across 16-step pages using <code>Pad Bank Up / Down</code>.","Execute hardware clip doubling using the <code>Function + Pad Bank Down</code> shortcut."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-14-2-1","title":"14.2.1: Sequencer Mode Initialization","blocks":[{"type":"step","title":"14.2.1: Sequencer Mode Initialization","blocks":[{"type":"list","items":["<strong>Activation</strong>: Hold <code>Shift</code> and press <strong>Pad 9 twice</strong>.","<strong>OLED Readout</strong>: Displays <code>Pad Mode: Sequencer (2/2)</code>.","<strong>Track Context Behavior</strong>:","<em>MIDI Track (No Clip Present)</em>: The 16 pads appear empty. Tapping any pad <strong>automatically instantiates a new 1-bar MIDI clip</strong> in the focused Session slot and places a note on that step.","<em>MIDI Track (Clip Present)</em>: The 16 pads instantly populate with the active notes of the selected clip.","<em>Audio Track Focused</em>: The pads remain unlit, as audio clips cannot be step-sequenced."],"ordered":false}]}],"minutes":8},{"id":"launchkey-l-14-2-2","title":"14.2.2: 16-Step Grid Layout & Playhead Telemetry","blocks":[{"type":"step","title":"14.2.2: 16-Step Grid Layout & Playhead Telemetry","blocks":[{"type":"prose","html":"The 16 pads represent a single 16-step bar of 16th notes:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">                SEQUENCER 16-STEP GRID TOPOLOGY\n+---------------------------------------------------------------+\n| [Step 1] [Step 2] [Step 3] [Step 4] [Step 5] [Step 6] [Step 7] [Step 8] | (Top Row)\n| [Step 9] [Step 10][Step 11][Step 12][Step 13][Step 14][Step 15][Step 16]| (Bottom Row)\n+---------------------------------------------------------------+</pre>"},{"type":"list","items":["<strong>Step States</strong>:","<strong>Populated Step</strong>: Illuminates in the active <strong>Track Color</strong>.","<strong>Empty Step</strong>: Unlit / extinguished.","<strong>Real-Time Playhead</strong>: A <strong>solid white LED</strong> sweeps across the 16 pads in exact synchronization with Ableton Live’s playhead."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-14-2-3","title":"14.2.3: Multi-Bar Page Navigation","blocks":[{"type":"step","title":"14.2.3: Multi-Bar Page Navigation","blocks":[{"type":"prose","html":"For clips longer than 1 bar (16 steps):"},{"type":"list","items":["Pressing <code>Pad Bank Up / Down</code> navigates across sequence pages:","Page 1: Steps 1–16 (Bar 1)","Page 2: Steps 17–32 (Bar 2)","Page 3: Steps 33–48 (Bar 3)","Page 4: Steps 49–64 (Bar 4)"],"ordered":false}]}],"minutes":8},{"id":"launchkey-l-14-2-4","title":"14.2.4: Clip Length Doubling","blocks":[{"type":"step","title":"14.2.4: Clip Length Doubling","blocks":[{"type":"prose","html":"To rapidly extend a 1-bar loop into a 2-bar progression without touching the computer:"},{"type":"list","items":["Hold <strong><code>Function</code></strong> and press <strong><code>Pad Bank Down</code></strong>.","Live instantly duplicates the entire clip content, doubling the clip length (e.g., 1 bar -&gt; 2 bars, or 2 bars -&gt; 4 bars) and navigating the pads to the newly created page."],"ordered":false}]},{"type":"step","title":"Operational Rules Summary","blocks":[{"type":"list","items":["<strong>mustCover</strong>: Mode entry (<code>Shift + Pad 9</code> twice); automatic clip creation on empty slots; audio track exclusion; 16-step layout + white playhead; multi-bar page navigation; clip doubling (<code>Function + Pad Bank Down</code>).","<strong>mustNotCover</strong>: Treating the hardware sequencer as a substitute for full DAW arrangement editing."],"ordered":false}]},{"type":"step","title":"Practical Guided Task & Assessment Checkpoint","blocks":[{"type":"prose","html":"<strong>Task</strong>: Focus an empty MIDI track in Ableton Live. Enter Sequencer Mode (<code>Shift + Pad 9</code> twice). Tap Pad 1, Pad 5, Pad 9, and Pad 13 to create a 4-on-the-floor beat. Verify Live automatically creates a 1-bar MIDI clip. Execute <code>Function + Pad Bank Down</code> to double the clip to 2 bars."},{"type":"prose","html":"<strong>Checkpoint Validation</strong>:"},{"type":"list","items":["Live automatically generates a new MIDI clip.","4 notes appear at quarter-note intervals (Steps 1, 5, 9, 13).","Clip length extends to 2 bars (32 steps) in Live's Clip View."],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"launchkey-m-14-3-3","code":"14.3","title":"Live Pad Subsystems: Clip Launch, Step Sequencer & Drums","blurb":"The Ableton Live Step Sequencer on the Launchkey MK4 61 dynamically adapts its engine architecture based on the instrument type on the focused track. When targeting a Drum Rack, it functions as a monophonic-per-voice Drum Sequencer with key","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"launchkey-l-o-44","title":"Section overview","blocks":[{"type":"step","title":"Section 14.3 — Drum Rack & Melodic Step Sequencing","blocks":[{"type":"heading","text":"Module Overview","level":3},{"type":"prose","html":"The Ableton Live Step Sequencer on the Launchkey MK4 61 dynamically adapts its engine architecture based on the instrument type on the focused track. When targeting a Drum Rack, it functions as a monophonic-per-voice <strong>Drum Sequencer</strong> with keybed voice selection. When targeting standard synthesizers, it operates as a polyphonic <strong>Melodic Sequencer</strong> with multi-step entry, note duplication, micro-timing nudge, and deep note parameter editing via continuous encoders."},{"type":"heading","text":"Learning Objectives","level":3},{"type":"list","items":["Formulate the operational difference between the Drum Sequencer and Melodic Sequencer.","Select drum voices dynamically from the 61-key keybed.","Execute step programming using both entry methods (Play-then-Press and Hold-then-Play).","Apply batch step programming across multiple held pads.","Duplicate step patterns using the <code>Function</code> duplication protocol.","Edit per-step note parameters (Velocity, Length, Fine, Nudge) using Encoders 1–4.","Navigate and select active session clips using the <code>Scene Launch &gt;</code> clip selection matrix."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-14-3-1","title":"14.3.1: Drum Sequencer vs. Melodic Sequencer","blocks":[{"type":"step","title":"14.3.1: Drum Sequencer vs. Melodic Sequencer","blocks":[{"type":"list","items":["<strong>Drum Sequencer (Drum Rack Focused)</strong>:","The 16 pads represent the 16 step gates for a <strong>single drum voice</strong> (e.g., Kick Drum).","<strong>Keybed Voice Selection</strong>: Striking any key on the keybed instantly selects that drum voice (e.g., striking <code>C1</code> selects Kick, <code>D1</code> selects Snare, <code>F#1</code> selects Closed Hat). The pads immediately update to display the active rhythm steps for that specific drum.","<strong>Melodic Sequencer (Standard Synthesizers / Samplers)</strong>:","Polyphonic step sequencing across any pitch or chord voicing."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-14-3-2","title":"14.3.2: Melodic Step Entry Methods","blocks":[{"type":"step","title":"14.3.2: Melodic Step Entry Methods","blocks":[{"type":"prose","html":"The Launchkey MK4 61 supports two intuitive methods for entering melodic steps:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------------+\n|                    MELODIC STEP ENTRY WORKFLOWS                               |\n+-------------------+-----------------------------------------------------------+\n| Workflow Method   | Step-by-Step Execution Sequence                           |\n+-------------------+-----------------------------------------------------------+\n| **Method 1:**     | 1. Play a note or chord on the keybed and release.        |\n| **Play-Then-Press**| 2. The internal buffer remembers the notes.              |\n|                   | 3. Tap any pad (e.g., Step 1, Step 5) to stamp the notes. |\n+-------------------+-----------------------------------------------------------+\n| **Method 2:**     | 1. Press and HOLD the target step pad (e.g., Step 9).     |\n| **Hold-Then-Play**| 2. While holding the pad, play the desired key/chord.     |\n|                   | 3. Release the pad. The notes are written to that step.   |\n+-------------------+-----------------------------------------------------------+</pre>"},{"type":"prose","html":"<em>Batch Multi-Step Entry</em>: Holding <strong>multiple pads simultaneously</strong> (e.g., Steps 1, 5, 9, 13) and playing a chord writes that exact chord voicing to all held steps at once."}]}],"minutes":8},{"id":"launchkey-l-14-3-3","title":"14.3.3: Step Note Duplication","blocks":[{"type":"step","title":"14.3.3: Step Note Duplication","blocks":[{"type":"prose","html":"To copy a complex chord voicing or drum step to a new position:"},{"type":"list","items":["Press <code>Function</code> once (the OLED screen displays <code>Sequencer: Duplicate</code>).","Press and <strong>HOLD the source step pad</strong>.","While holding the source pad, <strong>press the destination step pad</strong>.","The notes, velocity, and gate parameters are instantly cloned to the destination step."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-14-3-4","title":"14.3.4: Step Note Edit Encoders (Micro-Editing)","blocks":[{"type":"step","title":"14.3.4: Step Note Edit Encoders (Micro-Editing)","blocks":[{"type":"prose","html":"While pressing and holding any step pad, Encoders 1–4 automatically switch to dedicated <strong>Step Note Editors</strong>:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------------+\n|                    STEP NOTE EDIT ENCODER MATRIX                              |\n+---------------+-------------------+---------------------+---------------------+\n| Encoder       | Parameter Name    | Permitted Values    | Operational Scope   |\n+---------------+-------------------+---------------------+---------------------+\n| **Encoder 1** | **Velocity**      | **1 – 127**         | Step strike dynamic |\n| **Encoder 2** | **Length (Coarse)**| **1 – 16 Steps**   | Full-step duration  |\n| **Encoder 3** | **Fine (Fraction)**| **0.1 – 0.9 Steps**| Fractional length   |\n| **Encoder 4** | **Nudge**         | **-20% to +70%**    | Micro-timing groove |\n+---------------+-------------------+---------------------+---------------------+</pre>"},{"type":"prose","html":"<em>Nudge Edge Constraint</em>: Step Nudge cannot be applied to the first or last step of a clip boundary to prevent notes from wrapping out of bounds."}]}],"minutes":8},{"id":"launchkey-l-14-3-5","title":"14.3.5: Interactive Clip Selection","blocks":[{"type":"step","title":"14.3.5: Interactive Clip Selection","blocks":[{"type":"prose","html":"To switch the step sequencer to a different clip without touching the computer mouse:"},{"type":"list","items":["Press <code>Scene Launch &gt;</code>. The OLED screen displays <code>Sequencer Select Clip</code>.","The pad matrix displays all available session clips in their native track colors (empty slots display dim red).","Tap the desired pad to focus that clip.","Press <code>Scene Launch &gt;</code> again to return to 16-step sequencing."],"ordered":true}]},{"type":"step","title":"Operational Rules Summary","blocks":[{"type":"list","items":["<strong>mustCover</strong>: Drum vs Melodic sequencer; keybed drum selection (C1 kick, D1 snare); Play-then-Press and Hold-then-Play entry; batch multi-step entry; Function duplication; full 4-encoder Step Note Edit table (Velocity, Length, Fine, Nudge -20% to +70%); Scene Launch clip selector.","<strong>mustNotCover</strong>: Bitwig-specific chance/repeat parameters within the Ableton Live chapter (Bitwig is covered in Module 16)."],"ordered":false}]},{"type":"step","title":"Practical Guided Task & Assessment Checkpoint","blocks":[{"type":"prose","html":"<strong>Task</strong>: On a Drum Rack track, select Kick (C1) and program Steps 1 and 9. Strike D1 on the keybed to switch to Snare, and program Steps 5 and 13. Hold Step 5 and adjust <strong>Velocity</strong> (Encoder 1) to 127 and <strong>Nudge</strong> (Encoder 4) to +15%."},{"type":"prose","html":"<strong>Checkpoint Validation</strong>:"},{"type":"list","items":["Striking keybed notes switches the active drum voice seamlessly.","Step Note Encoders adjust velocity and micro-timing in real time.","Programmed pattern plays with humanized groove in Ableton Live."],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"launchkey-m-14-4-4","code":"14.4","title":"Live Pad Subsystems: Clip Launch, Step Sequencer & Drums","blurb":"When targeting an Ableton Live Drum Rack, switching the Launchkey MK4 61 pads to Drum Mode provides a velocity-sensitive, pressure-expressive 16-pad playing surface. This module covers DAW track color mirroring, channel routing alignment, D","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"launchkey-l-o-45","title":"Section overview","blocks":[{"type":"step","title":"Section 14.4 — Live Drum Rack Pad Mode Integration","blocks":[{"type":"heading","text":"Module Overview","level":3},{"type":"prose","html":"When targeting an Ableton Live Drum Rack, switching the Launchkey MK4 61 pads to <strong>Drum Mode</strong> provides a velocity-sensitive, pressure-expressive 16-pad playing surface. This module covers DAW track color mirroring, channel routing alignment, Drum Rack cell mapping, and aftertouch modulation routing inside Live's native sampler instruments."},{"type":"heading","text":"Learning Objectives","level":3},{"type":"list","items":["Engage Drum Mode within an active Ableton Live session via <code>Shift + Pad 10</code>.","Formulate the alignment between the 16 hardware pads (C1–D♯2 on Channel 10) and standard 16-pad Drum Rack groups.","Detail how the pads dynamically inherit track color metadata from Ableton Live.","Route Polyphonic Aftertouch from the pads into Ableton Live’s Simpler/Sampler modulation matrix."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-14-4-1","title":"14.4.1: Live Drum Mode Initialization & Color Mirroring","blocks":[{"type":"step","title":"14.4.1: Live Drum Mode Initialization & Color Mirroring","blocks":[{"type":"list","items":["<strong>Activation</strong>: Hold <code>Shift</code> and press <strong>Pad 10</strong> (silkscreened <code>Drum</code>).","<strong>Color Mirroring</strong>:","In standalone mode, pads illuminate solid blue.","In an active Ableton Live session, the pads <strong>automatically inherit the exact Track Color</strong> assigned to the Drum Rack track in Live.","Populated drum cells illuminate brightly; empty/unassigned cells remain unlit."],"ordered":false}]}],"minutes":8},{"id":"launchkey-l-14-4-2","title":"14.4.2: Note Map & Channel Alignment","blocks":[{"type":"step","title":"14.4.2: Note Map & Channel Alignment","blocks":[{"type":"list","items":["In Live Drum Mode, the pads transmit on <strong>MIDI Channel 10</strong> across the standard General MIDI drum octave:","<strong>Pad 9 (Bottom-Left)</strong>: MIDI Note 36 (<code>C1</code> - Kick Drum).","<strong>Pad 11 (Bottom Row)</strong>: MIDI Note 38 (<code>D1</code> - Snare Drum).","<strong>Pad 12 (Bottom Row)</strong>: MIDI Note 42 (<code>F#1</code> - Closed Hat).","<strong>Pad 8 (Top-Right)</strong>: MIDI Note 51 (<code>D#2</code> - Ride Cymbal).","<em>Track Routing Directive</em>: Ensure the Ableton Live Drum Rack track has its MIDI From set to <code>Launchkey MK4 MIDI</code> and Channel set to <code>10</code> (or <code>All Channels</code>)."],"ordered":false}]}],"minutes":8},{"id":"launchkey-l-14-4-3","title":"14.4.3: Polyphonic Aftertouch in Live Drum Racks","blocks":[{"type":"step","title":"14.4.3: Polyphonic Aftertouch in Live Drum Racks","blocks":[{"type":"list","items":["<strong>Per-Pad Modulation</strong>: Each pad transmits independent polyphonic pressure (<code>0xA0</code>) into Live.","<strong>Instrument Modulation Routing</strong>:","In Live's <strong>Simpler</strong> or <strong>Sampler</strong> device inside a Drum Rack pad, open the Modulation tab.","Map <code>Pressure</code> (Poly Aftertouch) to modulate Pitch, Filter Cutoff, or Sample Start Point.","Pressing into a specific drum pad (e.g., a snare roll) dynamically opens its filter without altering the hi-hats or kick."],"ordered":true}]},{"type":"step","title":"Operational Rules Summary","blocks":[{"type":"list","items":["<strong>mustCover</strong>: Drum mode selection (<code>Shift + Pad 10</code>); track color inheritance; C1–D♯2 on Channel 10; Simpler/Sampler polyphonic aftertouch routing.","<strong>mustNotCover</strong>: Invention of 128-pad Push-style Drum Rack layouts."],"ordered":false}]},{"type":"step","title":"Practical Guided Task & Assessment Checkpoint","blocks":[{"type":"prose","html":"<strong>Task</strong>: In Ableton Live, load an official Core Drum Rack onto a track and color the track Orange. Engage Drum Mode (<code>Shift + Pad 10</code>). Verify all 16 pads illuminate in orange. Strike Pad 9 to trigger the kick and Pad 11 to trigger the snare."},{"type":"prose","html":"<strong>Checkpoint Validation</strong>:"},{"type":"list","items":["Pads illuminate in the orange track color.","Pad 9 triggers C1 kick; Pad 11 triggers D1 snare.","Velocity response tracks naturally from 1 to 127."],"ordered":false}]}],"minutes":8}],"exercises":[]}]};
